# Embedded analytics sub-application mounted at: app.mount("/embedded/analytics", analytics_app)
analytics_app = FastAPI()

@analytics_app.get("/reports/{report_id}/raw")
async def get_raw_report_data(
    report_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    report = db.query(AnalyticsReport).filter(
        AnalyticsReport.id == report_id,
        AnalyticsReport.organization_id == current_user.organization_id
    ).first()
    if not report:
        raise HTTPException(status_code=404, detail="Report not found or access denied")
    return {"report_id": report_id, "data": report.raw_dataset}
